def compute(vars):
    purchase_obligations = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    ratio = purchase_obligations / total_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "purchase_obligations": purchase_obligations,
            "total_obligations": total_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "percentage",
            },
        },
    }
